python3 << 'EOF'
from pypdf import PdfReader

reader = PdfReader('/root/sc100-blank.pdf')

# Collect all field names from all pages
all_fields = set()

for page_num, page in enumerate(reader.pages):
    if "/Annots" in page:
        for annot in page["/Annots"]:
            obj = annot.get_object()
            if obj.get("/Subtype") == "/Widget" and "/T" in obj:
                field_name = obj["/T"]
                all_fields.add(str(field_name))

print("All form fields in the PDF:")
for field in sorted(all_fields):
    print(f"  - {field}")
