from pypdf import PdfReader

reader = PdfReader('/root/sc100-filled.pdf')

# Extract and display filled fields
print("Verification of filled fields in /root/sc100-filled.pdf:\n")

for page_num, page in enumerate(reader.pages):
    if "/Annots" in page:
        for annot in page["/Annots"]:
            obj = annot.get_object()
            if obj.get("/Subtype") == "/Widget" and "/T" in obj:
                field_name = str(obj["/T"])
                field_value = obj.get("/V", "")

                # Only display fields that have values
                if field_value and field_value != "Off":
                    print(f"{field_name}: {field_value}")

